//! Nim: `azul.nim` (generated by `doc/src/codegen/v2/lang_nim`).
//!
//! Nim's idiomatic wrappers only exist for struct classes, so the generated
//! code uses the raw layer, which keeps the C names: functions
//! (`AzCssProperty_textColor(..)`, variant constructors `AzLayoutWidth_px(..)`),
//! pure enums (`AzLayoutDisplay.Flex`), object constructors for structs and
//! `{.union.}` objects (`AzColorU(r: 255'u8, ..)`,
//! `AzLayoutWidthValue(Exact: AzLayoutWidthValueVariant_Exact(tag: 6, payload: ..))`).
//! A Vec is copied from an array by the generated `azVec` template (the C
//! function needs the address of the first element), strings by `azStr`.

use alloc::{
    format,
    string::{String, ToString},
    vec,
    vec::Vec,
};

use crate::codegen::{
    doc::{render, Doc},
    ir::{snake_to_lower_camel, EnumShape, Item, Module, Prim},
    lang::{
        escape_quoted, item_comments, item_doc, unicode_braced, variant_ctor_method, ExprSyntax,
    },
    lower_types::union_tag,
    CodegenBackend, GeneratedFile,
};

/// The Nim printer.
#[derive(Debug, Copy, Clone, Default)]
pub struct Nim;

const KEYWORDS: &[&str] = &[
    "addr", "and", "as", "asm", "bind", "block", "break", "case", "cast", "concept", "const",
    "continue", "converter", "defer", "discard", "distinct", "div", "do", "elif", "else", "end",
    "enum", "except", "export", "finally", "for", "from", "func", "if", "import", "in",
    "include", "interface", "is", "isnot", "iterator", "let", "macro", "method", "mixin", "mod",
    "nil", "not", "notin", "object", "of", "or", "out", "proc", "ptr", "raise", "ref", "return",
    "shl", "shr", "static", "template", "try", "tuple", "type", "using", "var", "when", "while",
    "xor", "yield",
];

/// Nim keywords compare style-insensitively; quote a name that matches one.
fn ident(name: &str) -> String {
    if KEYWORDS.contains(&name.to_ascii_lowercase().as_str()) {
        format!("`{name}`")
    } else {
        name.to_string()
    }
}

impl ExprSyntax for Nim {
    fn int(&self, value: i128, ty: Prim) -> String {
        let suffix = match ty {
            Prim::U8 => "'u8",
            Prim::U16 => "'u16",
            Prim::U32 => "'u32",
            Prim::U64 => "'u64",
            Prim::I8 => "'i8",
            Prim::I16 => "'i16",
            Prim::I32 => "'i32",
            Prim::I64 => "'i64",
            Prim::Usize => return format!("csize_t({value})"),
            Prim::Isize | Prim::F32 | Prim::F64 | Prim::Bool => "",
        };
        format!("{value}{suffix}")
    }

    fn float(&self, text: &str, _ty: Prim) -> String {
        match text {
            "nan" => "NaN".to_string(),
            "inf" => "Inf".to_string(),
            "-inf" => "NegInf".to_string(),
            _ => text.to_string(),
        }
    }

    fn boolean(&self, b: bool) -> String {
        b.to_string()
    }

    fn string(&self, s: &str) -> Doc {
        Doc::text(format!("azStr(\"{}\")", escape_quoted(s, &[], &unicode_braced)))
    }

    fn call(&self, class: &str, method: &str, args: Vec<Doc>, broken: bool) -> Doc {
        Doc::call(format!("Az{class}_{}", snake_to_lower_camel(method)), args, broken)
    }

    fn variant(&self, ty: &str, shape: EnumShape, variant: &str, args: Vec<Doc>, broken: bool) -> Doc {
        match shape {
            EnumShape::CLike => Doc::text(format!("Az{ty}.{}", ident(variant))),
            EnumShape::Tagged => Doc::call(
                format!("Az{ty}_{}", variant_ctor_method(variant)),
                args,
                broken,
            ),
            EnumShape::TaggedShadowed | EnumShape::Generic { .. } => {
                let tag = union_tag(ty, variant).unwrap_or(0);
                let mut inner = vec![Doc::text(format!("tag: {tag}"))];
                if let Some(payload) = args.into_iter().next() {
                    inner.push(Doc::cat(vec![Doc::text("payload: "), payload]));
                }
                Doc::call(
                    format!("Az{ty}"),
                    vec![Doc::cat(vec![
                        Doc::text(format!("{}: ", ident(variant))),
                        Doc::call(format!("Az{ty}Variant_{variant}"), inner, broken),
                    ])],
                    broken,
                )
            }
        }
    }

    fn strukt(&self, ty: &str, fields: Vec<(String, Doc)>, broken: bool) -> Doc {
        let fields = fields
            .into_iter()
            .map(|(k, v)| Doc::cat(vec![Doc::text(format!("{}: ", ident(&k))), v]))
            .collect();
        Doc::call(format!("Az{ty}"), fields, broken)
    }

    fn vec(&self, ty: &str, _elem: &str, items: Vec<Doc>, broken: bool) -> Doc {
        if items.is_empty() {
            return Doc::text(format!("Az{ty}_create()"));
        }
        Doc::cat(vec![
            Doc::text(format!("azVec(Az{ty}_copyFromPtr, ")),
            Doc::list("[", items, ", ", "]", false, broken, true),
            Doc::text(")"),
        ])
    }

    fn unsupported(&self, what: &str) -> Doc {
        Doc::text(format!("(raise newException(ValueError, {:?}))", format!("not expressible: {what}")))
    }
}

const HELPERS: &str = r#"template azVec(copy, items: untyped): untyped =
  block:
    var arr = items
    copy(addr arr[0], csize_t(arr.len))

proc azStr(s: string): AzString =
  AzString_fromUtf8(cast[ptr uint8](s.cstring), csize_t(s.len))
"#;

fn item_fn(item: &Item) -> String {
    let mut out = String::new();
    for line in &item_comments(&Nim, item) {
        out.push_str(&format!("# {line}\n"));
    }
    let name = item.name.lower_camel();
    match item_doc(&Nim, item) {
        Ok(doc) => out.push_str(&format!(
            "proc {name}*(): Az{} =\n  {}\n",
            item.ty,
            render(&doc, "  ", 1)
        )),
        Err(reason) => out.push_str(&format!(
            "# not expressible with the Nim bindings: {reason}\n"
        )),
    }
    out
}

impl CodegenBackend for Nim {
    fn lang(&self) -> &'static str {
        "nim"
    }

    fn display_name(&self) -> &'static str {
        "Nim"
    }

    fn extension(&self) -> &'static str {
        "nim"
    }

    fn emit_module(&self, m: &Module) -> String {
        let mut out =
            String::from("# Generated by azul-css codegen (Nim). Do not edit by hand.\nimport azul\n\n");
        out.push_str(HELPERS);
        for item in &m.items {
            out.push('\n');
            out.push_str(&item_fn(item));
        }
        out
    }

    fn emit_project_files(&self, m: &Module) -> Vec<GeneratedFile> {
        let mut main = String::from(
            "# Copy target/codegen/azul.nim and libazul next to this file, then:\n#   nim c -d:release \
             -r main.nim\nimport styles\n",
        );
        for item in &m.items {
            let name = item.name.lower_camel();
            main.push_str(&format!(
                "\nlet {name}Value = {name}()\necho \"{name}: \", {name}Value.len, \" properties\"\n"
            ));
        }
        vec![
            GeneratedFile {
                path: "styles.nim".to_string(),
                contents: self.emit_module(m),
            },
            GeneratedFile {
                path: "main.nim".to_string(),
                contents: main,
            },
        ]
    }
}
